/* \uC778\uC811 \uBCF4\uB108\uC2A4 (\uC790\uCCB4 \uC124\uACC4): \uBC30\uB0AD\uC5D0\uC11C \uCE78\uC774 \uC0C1\uD558\uC88C\uC6B0\uB85C \uB9DE\uB2FF\uC740 \uC7A5\uBE44\uB07C\uB9AC \uD6A8\uACFC \uBCF4\uB108\uC2A4. \uC800\uC7A5 \uD615\uC2DD\uC740 \uADF8\uB300\uB85C, \uD30C\uC0DD \uAC12\uB9CC \uACC4\uC0B0 */
var ADJ_SAME=11,ADJ_CROSS=7,ADJ_CAP=30;
function adjInfo(sv){
  var g=[],x,y;
  for(y=0;y<6;y++)g.push([null,null,null,null,null,null]);
  sv.board.forEach(function(J){En(J.type,J.rot).forEach(function(c){var cx=J.x+c[0],cy=J.y+c[1];if(cx>=0&&cy>=0&&cx<6&&cy<6)g[cy][cx]=J})});
  var map=new Map();
  sv.board.forEach(function(J){map.set(J.id,{it:J,nbrs:new Map(),links:0,pct:0,mult:1})});
  for(y=0;y<6;y++)for(x=0;x<6;x++){
    var A=g[y][x];if(!A)continue;
    if(x+1<6){var B=g[y][x+1];if(B&&B!==A){map.get(A.id).nbrs.set(B.id,B);map.get(B.id).nbrs.set(A.id,A)}}
    if(y+1<6){var C=g[y+1][x];if(C&&C!==A){map.get(A.id).nbrs.set(C.id,C);map.get(C.id).nbrs.set(A.id,A)}}
  }
  map.forEach(function(v){
    var pct=0;
    v.nbrs.forEach(function(B){pct+=bn[B.type].kind===bn[v.it.type].kind?ADJ_SAME:ADJ_CROSS});
    v.links=v.nbrs.size;v.pct=Math.min(bn[v.it.type]&&bn[v.it.type].fused?45:ADJ_CAP,pct);v.mult=1+v.pct/100;
  });
  return map;
}
var adjKey=null,adjVal=null;
